<script setup lang="ts">
import { computed, ref, toRef, watch } from "vue";
import { useNumberFormat } from "../../../../plugins/numberFormat";
import {
  useThemeDetection,
  type Theme,
} from "../../../../composables/useThemeDetection";
import ChartMetricContainer from "../../Utils/ChartMetricContainer/ChartMetricContainer.vue";
import CardMetric from "../../Utils/CardMetric/CardMetric.vue";
import { FooterExport, type ExportFormat } from "../../Utils/FooterExport";
import Table, {
  type TableColumn,
  type TableSortDirection,
} from "../../Utils/Table/Table.vue";
import Select, {
  type KiutSelectOption,
} from "../../../../components/Inputs/Select.vue";

interface AgentDayData {
  date: string;
  agent_email: string;
  agent_name?: string | null;
  agent_tag?: string | null;
  assigned_count: number;
  closed_count: number;
  transferred_count?: number;
  abandoned_count?: number;
  avg_time_to_assign_seconds?: DurationInput;
  avg_conversation_duration_seconds?: DurationInput;
  day_total_assigned?: number;
  day_total_closed?: number;
  day_total_enqueued?: number;
  day_total_transferred?: number;
  day_total_abandoned?: number;
  day_avg_time_to_assign_seconds?: DurationInput;
  day_avg_conversation_duration_seconds?: DurationInput;
  connected_at?: string | null;
  disconnected_at?: string | null;
  online_time_seconds?: DurationInput;
}

interface AgentHumanConvData {
  airline_name?: string;
  start_date?: string;
  end_date?: string;
  total_assigned?: number;
  total_closed?: number;
  total_enqueued?: number;
  total_transferred?: number;
  total_abandoned?: number;
  avg_time_to_assign_seconds?: DurationInput;
  avg_conversation_duration_seconds?: DurationInput;
  agents_by_day?: AgentDayData[];
}

interface AgentTableRow {
  id: string;
  date?: string;
  dateSort?: number;
  agent_name: string;
  agent_email: string;
  handled: number;
  transferred: number;
  /** Per-agent abandoned count (chats abandoned while assigned to this agent). */
  abandoned: number;
  connected_at: string | null;
  disconnected_at: string | null;
  online_time_display: string | null;
  avg_assignation_seconds: number | null;
  avg_resolution_seconds: number | null;
  avg_assignation_display: string;
  avg_resolution_display: string;
}

type DurationInput = string | number | null | undefined;
type TableViewMode = "by_date" | "aggregated";
type SortKey =
  | "date"
  | "name"
  | "email"
  | "handled"
  | "transferred"
  | "abandoned"
  | "avgAssignation"
  | "avgResolution";

const props = withDefaults(
  defineProps<{
    data?: AgentHumanConvData;
    loading?: boolean;
    theme?: Theme;
    enableExport?: boolean;
    exportLoading?: boolean;
    previousTotalEnqueued?: number | null;
    previousTotalClosed?: number | null;
    previousTotalTransferred?: number | null;
    previousTotalAbandoned?: number | null;
    previousAvgTimeToAssignSeconds?: number | null;
    previousAvgConversationDurationSeconds?: number | null;
  }>(),
  {
    data: () => ({
      total_assigned: 0,
      total_closed: 0,
      total_enqueued: 0,
      total_transferred: 0,
      total_abandoned: 0,
      avg_time_to_assign_seconds: null as string | null,
      avg_conversation_duration_seconds: null as string | null,
      agents_by_day: [],
    }),
    loading: false,
    theme: undefined,
    enableExport: false,
    exportLoading: false,
    previousTotalEnqueued: null,
    previousTotalClosed: null,
    previousTotalTransferred: null,
    previousTotalAbandoned: null,
    previousAvgTimeToAssignSeconds: null,
    previousAvgConversationDurationSeconds: null,
  },
);

const emit = defineEmits<{
  open: [];
  export: [format: ExportFormat];
}>();

const handleExport = (format: ExportFormat) => {
  emit("export", format);
};

const { isDark } = useThemeDetection(toRef(props, "theme"));

const PLACEHOLDER_EMAILS = new Set(["—", "-", "–", ""]);

function isValidAgentEmail(email: string | null | undefined): boolean {
  const normalized = email?.trim() ?? "";
  return normalized.length > 0 && !PLACEHOLDER_EMAILS.has(normalized);
}

/** Filas con agente identificable y actividad (asignación, cierre o transferencia). */
function isDisplayableAgentRow(agent: AgentDayData): boolean {
  if (!isValidAgentEmail(agent.agent_email)) return false;
  const assigned = agent.assigned_count ?? 0;
  const closed = agent.closed_count ?? 0;
  const transferred = agent.transferred_count ?? 0;
  const abandoned = agent.abandoned_count ?? 0;
  return assigned > 0 || closed > 0 || transferred > 0 || abandoned > 0;
}

function getHandledCount(agent: AgentDayData): number {
  return agent.closed_count ?? 0;
}

function getTransferredCount(agent: AgentDayData): number {
  return agent.transferred_count ?? 0;
}

function getAgentAbandonedCount(agent: AgentDayData): number {
  return agent.abandoned_count ?? 0;
}

function getAbandonedCount(agent: AgentDayData): number {
  return agent.day_total_abandoned ?? 0;
}

function formatAgentName(name: string | null | undefined): string {
  const normalized = name?.trim();
  return normalized ? normalized : "—";
}

function formatOptionalDisplay(value: string | null | undefined): string {
  const normalized = value?.trim();
  return normalized ? normalized : "—";
}

function formatAbandonedDisplay(value: number | null | undefined): string {
  if (value === null || value === undefined) return "0";
  return formatNumber(value);
}

const displayAgentRows = computed(() =>
  (props.data?.agents_by_day ?? []).filter(isDisplayableAgentRow),
);

const hasAgentRows = computed(() => displayAgentRows.value.length > 0);

const hasData = computed(() => {
  const hasEnqueued = (props.data?.total_enqueued ?? 0) > 0;
  const hasTransferred = (props.data?.total_transferred ?? 0) > 0;
  const hasAbandoned = (props.data?.total_abandoned ?? 0) > 0;
  return hasAgentRows.value || hasEnqueued || hasTransferred || hasAbandoned;
});

const tableViewMode = ref<TableViewMode>("by_date");
const tableViewModeOptions: KiutSelectOption<TableViewMode>[] = [
  { value: "by_date", label: "By date" },
  { value: "aggregated", label: "Aggregated" },
];
const sortKey = ref<SortKey>("date");
const sortDirection = ref<TableSortDirection>("desc");

const MAX_VISIBLE_ROWS = 6;

watch(tableViewMode, (mode) => {
  if (mode === "aggregated") {
    sortKey.value = "name";
    sortDirection.value = "asc";
  } else {
    sortKey.value = "date";
    sortDirection.value = "desc";
  }
});

function computeChangePercent(
  current: number,
  previous: number | null | undefined,
): number | null {
  if (previous === null || previous === undefined) return null;
  if (previous === 0) return current > 0 ? 100 : 0;
  return ((current - previous) / previous) * 100;
}

function formatChangeLabel(percent: number): string {
  const pct = percent.toFixed(1);
  if (percent > 0) return `+${pct}%`;
  return `${pct}%`;
}

function trendBadgeClass(percent: number, lowerIsBetter = false): string {
  const effective = lowerIsBetter ? -percent : percent;
  if (effective > 0) return "change-badge--up";
  if (effective < 0) return "change-badge--down";
  return "change-badge--neutral";
}

function buildDurationTrend(
  current: number | null,
  previous: number | null | undefined,
): { label: string; class: string } | null {
  if (current === null) return null;
  const change = computeChangePercent(current, previous);
  if (change === null) return null;
  return {
    label: formatChangeLabel(change),
    class: trendBadgeClass(change, true),
  };
}

function hhmmssToSeconds(val: DurationInput): number | null {
  if (val === null || val === undefined || val === "") return null;
  if (typeof val === "number") {
    return Number.isFinite(val) ? val : null;
  }
  const trimmed = val.trim();
  if (!trimmed) return null;
  if (trimmed.includes(":")) {
    const parts = trimmed.split(":").map(Number);
    if (parts.length !== 3 || parts.some(isNaN)) return null;
    return parts[0] * 3600 + parts[1] * 60 + parts[2];
  }
  const numeric = Number(trimmed);
  return Number.isFinite(numeric) ? numeric : null;
}

function secondsToHhmmss(seconds: number): string {
  const total = Math.round(seconds);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

function formatDurationDisplay(val: DurationInput): string {
  const seconds = hhmmssToSeconds(val);
  if (seconds === null) return "—";
  if (typeof val === "string" && val.includes(":")) return val.trim();
  return secondsToHhmmss(seconds);
}

const totalEnqueued = computed(() => props.data?.total_enqueued ?? 0);
const totalClosed = computed(() => props.data?.total_closed ?? 0);
const totalTransferred = computed(() => props.data?.total_transferred ?? 0);
const totalAbandoned = computed(() => props.data?.total_abandoned ?? 0);
const avgAssignSeconds = computed(
  () => props.data?.avg_time_to_assign_seconds ?? null,
);
const avgResolutionSeconds = computed(
  () => props.data?.avg_conversation_duration_seconds ?? null,
);

const closedPctLabel = computed(() => {
  if (totalEnqueued.value <= 0) return null;
  const pct = ((totalClosed.value / totalEnqueued.value) * 100).toFixed(1);
  return `(${pct}%)`;
});

const assignDurationTrend = computed(() =>
  buildDurationTrend(
    hhmmssToSeconds(avgAssignSeconds.value),
    props.previousAvgTimeToAssignSeconds,
  ),
);

const resolutionDurationTrend = computed(() =>
  buildDurationTrend(
    hhmmssToSeconds(avgResolutionSeconds.value),
    props.previousAvgConversationDurationSeconds,
  ),
);

function mapAgentToRow(agent: AgentDayData, index: number): AgentTableRow {
  return {
    id: `${agent.date}-${agent.agent_email}-${index}`,
    date: agent.date,
    dateSort: new Date(agent.date).getTime(),
    agent_name: agent.agent_name ?? "",
    agent_email: agent.agent_email,
    handled: getHandledCount(agent),
    transferred: getTransferredCount(agent),
    abandoned: getAgentAbandonedCount(agent),
    connected_at: agent.connected_at ?? null,
    disconnected_at: agent.disconnected_at ?? null,
    online_time_display:
      agent.online_time_seconds == null || agent.online_time_seconds === ""
        ? null
        : formatDurationDisplay(agent.online_time_seconds),
    avg_assignation_seconds: hhmmssToSeconds(agent.avg_time_to_assign_seconds),
    avg_resolution_seconds: hhmmssToSeconds(
      agent.avg_conversation_duration_seconds,
    ),
    avg_assignation_display: formatDurationDisplay(
      agent.avg_time_to_assign_seconds,
    ),
    avg_resolution_display: formatDurationDisplay(
      agent.avg_conversation_duration_seconds,
    ),
  };
}

function aggregateAgents(agents: AgentDayData[]): AgentTableRow[] {
  const map = new Map<
    string,
    {
      agent_name: string;
      agent_email: string;
      handled: number;
      transferred: number;
      abandoned: number;
      assignSum: number;
      assignWeight: number;
      resolutionSum: number;
      resolutionWeight: number;
    }
  >();

  for (const agent of agents) {
    if (!isDisplayableAgentRow(agent)) continue;

    const key = agent.agent_email.trim();
    if (!map.has(key)) {
      map.set(key, {
        agent_name: agent.agent_name?.trim() ?? "",
        agent_email: key,
        handled: 0,
        transferred: 0,
        abandoned: 0,
        assignSum: 0,
        assignWeight: 0,
        resolutionSum: 0,
        resolutionWeight: 0,
      });
    }

    const acc = map.get(key)!;
    const assigned = agent.assigned_count ?? 0;
    const closed = agent.closed_count ?? 0;
    acc.handled += getHandledCount(agent);
    acc.transferred += getTransferredCount(agent);
    acc.abandoned += getAgentAbandonedCount(agent);

    if (agent.agent_name?.trim()) {
      acc.agent_name = agent.agent_name.trim();
    }

    const assignSec = hhmmssToSeconds(agent.avg_time_to_assign_seconds);
    if (assignSec !== null && assigned > 0) {
      acc.assignSum += assignSec * assigned;
      acc.assignWeight += assigned;
    }

    const resSec = hhmmssToSeconds(agent.avg_conversation_duration_seconds);
    if (resSec !== null && closed > 0) {
      acc.resolutionSum += resSec * closed;
      acc.resolutionWeight += closed;
    }
  }

  return Array.from(map.values()).map((acc, index) => {
    const assignAvg =
      acc.assignWeight > 0 ? acc.assignSum / acc.assignWeight : null;
    const resAvg =
      acc.resolutionWeight > 0
        ? acc.resolutionSum / acc.resolutionWeight
        : null;
    return {
      id: `agg-${acc.agent_email}-${index}`,
      agent_name: acc.agent_name,
      agent_email: acc.agent_email,
      handled: acc.handled,
      transferred: acc.transferred,
      abandoned: acc.abandoned,
      connected_at: null,
      disconnected_at: null,
      online_time_display: null,
      avg_assignation_seconds: assignAvg,
      avg_resolution_seconds: resAvg,
      avg_assignation_display:
        assignAvg !== null ? secondsToHhmmss(assignAvg) : "—",
      avg_resolution_display: resAvg !== null ? secondsToHhmmss(resAvg) : "—",
    };
  });
}

const baseTableRows = computed<AgentTableRow[]>(() => {
  const agents = displayAgentRows.value;
  if (tableViewMode.value === "aggregated") {
    return aggregateAgents(agents);
  }
  return agents.map(mapAgentToRow);
});

function compareRows(
  a: AgentTableRow,
  b: AgentTableRow,
  key: SortKey,
  direction: TableSortDirection,
): number {
  const dir = direction === "asc" ? 1 : -1;
  let cmp = 0;

  switch (key) {
    case "date":
      cmp = (a.dateSort ?? 0) - (b.dateSort ?? 0);
      break;
    case "name":
      cmp = (a.agent_name || "").localeCompare(b.agent_name || "", undefined, {
        sensitivity: "base",
      });
      break;
    case "email":
      cmp = a.agent_email.localeCompare(b.agent_email, undefined, {
        sensitivity: "base",
      });
      break;
    case "handled":
      cmp = a.handled - b.handled;
      break;
    case "transferred":
      cmp = a.transferred - b.transferred;
      break;
    case "abandoned":
      cmp = (a.abandoned ?? 0) - (b.abandoned ?? 0);
      break;
    case "avgAssignation":
      cmp =
        (a.avg_assignation_seconds ?? Number.NEGATIVE_INFINITY) -
        (b.avg_assignation_seconds ?? Number.NEGATIVE_INFINITY);
      break;
    case "avgResolution":
      cmp =
        (a.avg_resolution_seconds ?? Number.NEGATIVE_INFINITY) -
        (b.avg_resolution_seconds ?? Number.NEGATIVE_INFINITY);
      break;
  }

  if (cmp !== 0) return cmp * dir;

  if (tableViewMode.value === "by_date" && key !== "date") {
    const dateCmp = (b.dateSort ?? 0) - (a.dateSort ?? 0);
    if (dateCmp !== 0) return dateCmp;
  }

  return (a.agent_name || "").localeCompare(b.agent_name || "", undefined, {
    sensitivity: "base",
  });
}

const sortedTableRows = computed(() => {
  const rows = [...baseTableRows.value];
  rows.sort((a, b) => compareRows(a, b, sortKey.value, sortDirection.value));
  return rows;
});

const tableRows = computed(
  (): Record<string, unknown>[] =>
    sortedTableRows.value as unknown as Record<string, unknown>[],
);

const agentTableColumns = computed<TableColumn[]>(() => {
  const cols: TableColumn[] = [];

  if (tableViewMode.value === "by_date") {
    cols.push({
      key: "date",
      label: "Date",
      align: "left",
      sortable: true,
    });
  }

  cols.push(
    { key: "name", label: "Name", align: "left", sortable: true },
    { key: "email", label: "Email", align: "left", sortable: true },
    { key: "handled", label: "Handled", align: "center", sortable: true },
    {
      key: "transferred",
      label: "Transferred",
      align: "center",
      sortable: true,
    },
    {
      key: "abandoned",
      label: "Abandoned",
      align: "center",
      sortable: true,
    },
    {
      key: "connected",
      label: "Connected",
      align: "center",
      sortable: false,
    },
    {
      key: "disconnected",
      label: "Disconnected",
      align: "center",
      sortable: false,
    },
    {
      key: "onlineTime",
      label: "Online time",
      align: "center",
      sortable: false,
    },
    {
      key: "avgAssignation",
      label: "Avg Assignation",
      align: "center",
      sortable: true,
    },
    {
      key: "avgResolution",
      label: "Avg Resolution",
      align: "center",
      sortable: true,
    },
  );

  return cols;
});

function onSortColumn(key: string): void {
  const sortableKey = key as SortKey;

  if (sortKey.value === sortableKey) {
    sortDirection.value = sortDirection.value === "asc" ? "desc" : "asc";
    return;
  }

  sortKey.value = sortableKey;
  if (sortableKey === "date") {
    sortDirection.value = "desc";
  } else if (sortableKey === "name" || sortableKey === "email") {
    sortDirection.value = "asc";
  } else {
    sortDirection.value = "desc";
  }
}

const formatNumber = (value: number | undefined | null): string => {
  if (value === undefined || value === null) return "0";
  return useNumberFormat(value);
};

const formatDurationSeconds = (value: number | null | undefined): string => {
  if (value === undefined || value === null) {
    return "—";
  }
  if (value < 60) {
    return `${Math.round(value)}s`;
  }

  const totalSeconds = Math.round(value);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  if (minutes < 60) {
    return `${minutes}m ${seconds}s`;
  }

  const hours = Math.floor(minutes / 60);
  const remainingMinutes = minutes % 60;
  return `${hours}h ${remainingMinutes}m`;
};

const formatCompactDate = (dateStr: string): string => {
  const date = new Date(dateStr);
  return date.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
  });
};

defineExpose({ isDark });
</script>

